package com.codex.navigator;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexNavigatorPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexNavigatorPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.navigator;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CodexNavigatorConfig.GROUP)
public interface CodexNavigatorConfig extends Config
{
	String GROUP = "codexnavigator";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show focus in game",
		description = "Shows your focus goal and its next step in a small overlay",
		position = 1
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "suggestWithoutFocus",
		name = "Suggest when unfocused",
		description = "With no goal pinned, the overlay shows the best quest you can start right now",
		position = 2
	)
	default boolean suggestWithoutFocus()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeMiniquests",
		name = "Include miniquests",
		description = "Lists and suggests miniquests alongside quests",
		position = 3
	)
	default boolean includeMiniquests()
	{
		return true;
	}
}

package com.codex.navigator;

import com.codex.navigator.core.AccountSnapshot;
import com.codex.navigator.core.Goal;
import com.codex.navigator.core.GoalStore;
import com.codex.navigator.core.Plan;
import com.codex.navigator.core.Planner;
import com.codex.navigator.core.Recommender;
import com.codex.navigator.core.Step;
import com.codex.navigator.data.CodexData;
import com.codex.navigator.data.QuestDef;
import com.codex.navigator.overlay.FocusOverlay;
import com.codex.navigator.ui.Icons;
import com.codex.navigator.ui.NavigatorPanel;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Codex Navigator",
	description = "An account compass: every quest, diary and combat achievement tier, with the path to whatever you want next",
	tags = {"quest", "diary", "goal", "planner", "progress", "achievement", "codex"}
)
public class CodexNavigatorPlugin extends Plugin
{
	private static final String GOALS_KEY = "goals";
	private static final Type GOAL_LIST = new TypeToken<List<String>>()
	{
	}.getType();
	/** Varbits can change many times a second; refresh at most this often while they do. */
	private static final int REFRESH_TICKS = 2;

	private static final String[] DIARY_AREAS = {"Ardougne", "Desert", "Falador", "Fremennik", "Kandarin", "Karamja",
		"Kourend", "Lumbridge", "Morytania", "Varrock", "Western", "Wilderness"};
	private static final String[] DIARY_TIERS = {"Easy", "Medium", "Hard", "Elite"};
	// Complete flags per area, in DIARY_TIERS order. Karamja's first three tiers have no
	// complete flag, so their reward-claimed flags stand in, as Quest Helper does.
	private static final int[][] DIARY_VARBITS = {
		{VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE, VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE, VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE, VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE},
		{VarbitID.DESERT_DIARY_EASY_COMPLETE, VarbitID.DESERT_DIARY_MEDIUM_COMPLETE, VarbitID.DESERT_DIARY_HARD_COMPLETE, VarbitID.DESERT_DIARY_ELITE_COMPLETE},
		{VarbitID.FALADOR_DIARY_EASY_COMPLETE, VarbitID.FALADOR_DIARY_MEDIUM_COMPLETE, VarbitID.FALADOR_DIARY_HARD_COMPLETE, VarbitID.FALADOR_DIARY_ELITE_COMPLETE},
		{VarbitID.FREMENNIK_DIARY_EASY_COMPLETE, VarbitID.FREMENNIK_DIARY_MEDIUM_COMPLETE, VarbitID.FREMENNIK_DIARY_HARD_COMPLETE, VarbitID.FREMENNIK_DIARY_ELITE_COMPLETE},
		{VarbitID.KANDARIN_DIARY_EASY_COMPLETE, VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE, VarbitID.KANDARIN_DIARY_HARD_COMPLETE, VarbitID.KANDARIN_DIARY_ELITE_COMPLETE},
		{VarbitID.ATJUN_EASY_REWARD, VarbitID.ATJUN_MED_REWARD, VarbitID.ATJUN_HARD_REWARD, VarbitID.KARAMJA_DIARY_ELITE_COMPLETE},
		{VarbitID.KOUREND_DIARY_EASY_COMPLETE, VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE, VarbitID.KOUREND_DIARY_HARD_COMPLETE, VarbitID.KOUREND_DIARY_ELITE_COMPLETE},
		{VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE, VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE, VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE, VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE},
		{VarbitID.MORYTANIA_DIARY_EASY_COMPLETE, VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE, VarbitID.MORYTANIA_DIARY_HARD_COMPLETE, VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE},
		{VarbitID.VARROCK_DIARY_EASY_COMPLETE, VarbitID.VARROCK_DIARY_MEDIUM_COMPLETE, VarbitID.VARROCK_DIARY_HARD_COMPLETE, VarbitID.VARROCK_DIARY_ELITE_COMPLETE},
		{VarbitID.WESTERN_DIARY_EASY_COMPLETE, VarbitID.WESTERN_DIARY_MEDIUM_COMPLETE, VarbitID.WESTERN_DIARY_HARD_COMPLETE, VarbitID.WESTERN_DIARY_ELITE_COMPLETE},
		{VarbitID.WILDERNESS_DIARY_EASY_COMPLETE, VarbitID.WILDERNESS_DIARY_MEDIUM_COMPLETE, VarbitID.WILDERNESS_DIARY_HARD_COMPLETE, VarbitID.WILDERNESS_DIARY_ELITE_COMPLETE},
	};
	private static final int[] COMBAT_ACHIEVEMENT_VARBITS = {
		VarbitID.CA_TOTAL_TASKS_COMPLETED_EASY, VarbitID.CA_TOTAL_TASKS_COMPLETED_MEDIUM, VarbitID.CA_TOTAL_TASKS_COMPLETED_HARD,
		VarbitID.CA_TOTAL_TASKS_COMPLETED_ELITE, VarbitID.CA_TOTAL_TASKS_COMPLETED_MASTER, VarbitID.CA_TOTAL_TASKS_COMPLETED_GRANDMASTER,
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SkillIconManager skillIconManager;

	@Inject
	private Gson gson;

	@Inject
	private CodexNavigatorConfig config;

	private final GoalStore goals = new GoalStore();
	private final FocusOverlay overlay = new FocusOverlay();
	private final Map<String, Quest> questsByName = new HashMap<>();

	private Planner planner;
	private Recommender recommender;
	private NavigatorPanel panel;
	private NavigationButton navButton;

	private volatile AccountSnapshot snapshot = AccountSnapshot.empty();
	private int lastSignature;
	private boolean dirty;
	private int ticksSinceRefresh;

	@Provides
	CodexNavigatorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexNavigatorConfig.class);
	}

	@Override
	protected void startUp()
	{
		CodexData data = CodexData.load(gson);
		planner = new Planner(data);
		recommender = new Recommender(planner);
		for (Quest quest : Quest.values())
		{
			questsByName.put(quest.getName(), quest);
		}

		goals.setSaver(keys -> configManager.setRSProfileConfiguration(CodexNavigatorConfig.GROUP, GOALS_KEY, gson.toJson(keys)));
		goals.addListener(this::updateOverlay);
		loadGoals();

		panel = new NavigatorPanel(planner, recommender, goals, skillIconManager, config::includeMiniquests);
		navButton = NavigationButton.builder()
			.tooltip("Codex Navigator")
			.icon(Icons.compass(16))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);

		dirty = true;
		clientThread.invokeLater(this::refresh);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		questsByName.clear();
		snapshot = AccountSnapshot.empty();
		lastSignature = 0;
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			dirty = true;
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			publish(AccountSnapshot.empty());
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadGoals();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CodexNavigatorConfig.GROUP.equals(event.getGroup()) && !GOALS_KEY.equals(event.getKey()))
		{
			lastSignature = 0;
			dirty = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		ticksSinceRefresh++;
		if (dirty && ticksSinceRefresh >= REFRESH_TICKS)
		{
			refresh();
		}
	}

	private void loadGoals()
	{
		String json = configManager.getRSProfileConfiguration(CodexNavigatorConfig.GROUP, GOALS_KEY);
		List<String> keys = null;
		if (json != null && !json.isEmpty())
		{
			try
			{
				keys = gson.fromJson(json, GOAL_LIST);
			}
			catch (RuntimeException e)
			{
				keys = null;
			}
		}
		goals.load(keys);
	}

	/** Reads the account on the client thread and hands it to the panel if anything changed. */
	private void refresh()
	{
		dirty = false;
		ticksSinceRefresh = 0;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		AccountSnapshot.Builder b = new AccountSnapshot.Builder().loggedIn(true);
		Player local = client.getLocalPlayer();
		if (local != null)
		{
			b.playerName(local.getName()).combatLevel(local.getCombatLevel());
		}
		for (Skill skill : Skill.values())
		{
			b.skill(skill, client.getRealSkillLevel(skill), client.getSkillExperience(skill));
		}
		for (QuestDef def : planner.getData().quests())
		{
			Quest quest = questsByName.get(def.name);
			if (quest != null)
			{
				QuestState state = quest.getState(client);
				if (state != null)
				{
					b.quest(def.name, state);
				}
			}
		}
		b.questPoints(client.getVarpValue(VarPlayerID.QP));
		for (int area = 0; area < DIARY_AREAS.length; area++)
		{
			for (int tier = 0; tier < DIARY_TIERS.length; tier++)
			{
				if (client.getVarbitValue(DIARY_VARBITS[area][tier]) > 0)
				{
					b.diary(DIARY_AREAS[area] + " " + DIARY_TIERS[tier]);
				}
			}
		}
		for (int i = 0; i < COMBAT_ACHIEVEMENT_VARBITS.length; i++)
		{
			b.combatAchievements(CodexData.COMBAT_ACHIEVEMENT_TIERS[i], client.getVarbitValue(COMBAT_ACHIEVEMENT_VARBITS[i]));
		}
		b.combatAchievementPoints(client.getVarbitValue(VarbitID.CA_POINTS));
		publish(b.build());
	}

	private void publish(AccountSnapshot next)
	{
		int signature = next.signature();
		if (signature == lastSignature)
		{
			return;
		}
		lastSignature = signature;
		snapshot = next;
		updateOverlay();
		NavigatorPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(next));
		}
	}

	private void updateOverlay()
	{
		AccountSnapshot account = snapshot;
		if (!config.showOverlay() || !account.isLoggedIn() || planner == null)
		{
			overlay.setView(null);
			return;
		}
		Goal focus = goals.focus();
		if (focus != null)
		{
			Plan plan = planner.plan(focus, account);
			Step next = plan.getNext();
			overlay.setView(new FocusOverlay.View("CODEX  ·  FOCUS", plan.getTitle(), plan.getProgress(),
				next == null ? "Complete" : stepText(next)));
			return;
		}
		if (config.suggestWithoutFocus())
		{
			List<Recommender.Pick> picks = recommender.readyNow(account, config.includeMiniquests(), 1);
			if (!picks.isEmpty())
			{
				Recommender.Pick pick = picks.get(0);
				overlay.setView(new FocusOverlay.View("CODEX  ·  SUGGESTED", pick.getQuest().name, -1,
					pick.getReason() != null ? pick.getReason() : "Ready to start"));
				return;
			}
		}
		overlay.setView(null);
	}

	private static String stepText(Step step)
	{
		if (step.getKind() == Step.Kind.QUEST)
		{
			return (step.getStatus() == Step.Status.IN_PROGRESS ? "Continue " : "Start ") + step.getTitle();
		}
		return step.getTitle();
	}
}

package com.codex.navigator.core;

import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Experience;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * An immutable read of everything the planner needs, taken on the client thread
 * and handed to Swing. Quests that the client cannot report are simply absent.
 */
public final class AccountSnapshot
{
	private final boolean loggedIn;
	private final String playerName;
	private final Map<Skill, Integer> levels;
	private final Map<Skill, Integer> xp;
	private final Map<String, QuestState> quests;
	private final Set<String> diariesDone;
	private final Map<String, Integer> combatAchievementsDone;
	private final int questPoints;
	private final int combatLevel;
	private final int combatAchievementPoints;

	private AccountSnapshot(Builder b)
	{
		loggedIn = b.loggedIn;
		playerName = b.playerName;
		levels = Collections.unmodifiableMap(new EnumMap<>(b.levels));
		xp = Collections.unmodifiableMap(new EnumMap<>(b.xp));
		quests = Collections.unmodifiableMap(new HashMap<>(b.quests));
		diariesDone = Collections.unmodifiableSet(new HashSet<>(b.diariesDone));
		combatAchievementsDone = Collections.unmodifiableMap(new HashMap<>(b.combatAchievementsDone));
		questPoints = b.questPoints;
		combatLevel = b.combatLevel;
		combatAchievementPoints = b.combatAchievementPoints;
	}

	public static AccountSnapshot empty()
	{
		return new Builder().build();
	}

	public boolean isLoggedIn()
	{
		return loggedIn;
	}

	public String getPlayerName()
	{
		return playerName;
	}

	public int level(Skill skill)
	{
		return levels.getOrDefault(skill, skill == Skill.HITPOINTS ? 10 : 1);
	}

	public int xp(Skill skill)
	{
		Integer value = xp.get(skill);
		return value != null ? value : Experience.getXpForLevel(level(skill));
	}

	public int totalLevel()
	{
		int total = 0;
		for (Skill skill : Skill.values())
		{
			total += level(skill);
		}
		return total;
	}

	public QuestState quest(String name)
	{
		return quests.get(name);
	}

	public boolean questDone(String name)
	{
		return quests.get(name) == QuestState.FINISHED;
	}

	public boolean knowsQuest(String name)
	{
		return quests.containsKey(name);
	}

	public boolean diaryDone(String name)
	{
		return diariesDone.contains(name);
	}

	public int diariesCompleted()
	{
		return diariesDone.size();
	}

	public int combatAchievementsDone(String tier)
	{
		return combatAchievementsDone.getOrDefault(tier, 0);
	}

	public int getQuestPoints()
	{
		return questPoints;
	}

	public int getCombatLevel()
	{
		return combatLevel;
	}

	public int getCombatAchievementPoints()
	{
		return combatAchievementPoints;
	}

	/** Changes whenever anything the panel shows changes, so unchanged ticks can be skipped. */
	public int signature()
	{
		return java.util.Objects.hash(loggedIn, playerName, levels, xp, quests, diariesDone, combatAchievementsDone,
			questPoints, combatLevel, combatAchievementPoints);
	}

	public static final class Builder
	{
		private boolean loggedIn;
		private String playerName;
		private final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		private final Map<String, QuestState> quests = new HashMap<>();
		private final Set<String> diariesDone = new HashSet<>();
		private final Map<String, Integer> combatAchievementsDone = new HashMap<>();
		private int questPoints;
		private int combatLevel = 3;
		private int combatAchievementPoints;

		public Builder loggedIn(boolean value)
		{
			loggedIn = value;
			return this;
		}

		public Builder playerName(String value)
		{
			playerName = value;
			return this;
		}

		public Builder skill(Skill skill, int level, int experience)
		{
			levels.put(skill, level);
			xp.put(skill, experience);
			return this;
		}

		public Builder level(Skill skill, int level)
		{
			levels.put(skill, level);
			return this;
		}

		public Builder quest(String name, QuestState state)
		{
			quests.put(name, state);
			return this;
		}

		public Builder diary(String name)
		{
			diariesDone.add(name);
			return this;
		}

		public Builder combatAchievements(String tier, int done)
		{
			combatAchievementsDone.put(tier, done);
			return this;
		}

		public Builder questPoints(int value)
		{
			questPoints = value;
			return this;
		}

		public Builder combatLevel(int value)
		{
			combatLevel = value;
			return this;
		}

		public Builder combatAchievementPoints(int value)
		{
			combatAchievementPoints = value;
			return this;
		}

		public AccountSnapshot build()
		{
			return new AccountSnapshot(this);
		}
	}
}

package com.codex.navigator.core;

import java.util.Objects;

/** Something the player wants: a quest, a diary tier or the quest cape. */
public final class Goal
{
	public enum Type
	{
		QUEST("quest"),
		DIARY("diary"),
		QUEST_CAPE("cape");

		private final String prefix;

		Type(String prefix)
		{
			this.prefix = prefix;
		}
	}

	public static final Goal QUEST_CAPE = new Goal(Type.QUEST_CAPE, "Quest point cape");

	private final Type type;
	private final String name;

	public Goal(Type type, String name)
	{
		this.type = type;
		this.name = name;
	}

	public static Goal quest(String name)
	{
		return new Goal(Type.QUEST, name);
	}

	public static Goal diary(String name)
	{
		return new Goal(Type.DIARY, name);
	}

	public Type getType()
	{
		return type;
	}

	public String getName()
	{
		return name;
	}

	/** A stable string for saving pinned goals, such as {@code quest:Dragon Slayer I}. */
	public String key()
	{
		return type.prefix + ":" + name;
	}

	public static Goal fromKey(String key)
	{
		int split = key.indexOf(':');
		if (split < 0)
		{
			return null;
		}
		String prefix = key.substring(0, split);
		String name = key.substring(split + 1);
		for (Type type : Type.values())
		{
			if (type.prefix.equals(prefix))
			{
				return type == Type.QUEST_CAPE ? QUEST_CAPE : new Goal(type, name);
			}
		}
		return null;
	}

	@Override
	public boolean equals(Object o)
	{
		if (!(o instanceof Goal))
		{
			return false;
		}
		Goal other = (Goal) o;
		return type == other.type && name.equals(other.name);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(type, name);
	}

	@Override
	public String toString()
	{
		return key();
	}
}

package com.codex.navigator.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

/**
 * The player's pinned goals, in order; the first is the focus. Persistence is
 * left to the plugin, which saves {@link #keys()} per RuneScape profile.
 */
public final class GoalStore
{
	private final List<Goal> goals = new CopyOnWriteArrayList<>();
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
	private Consumer<List<String>> saver = keys -> { };

	public void setSaver(Consumer<List<String>> saver)
	{
		this.saver = saver;
	}

	public void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	public List<Goal> goals()
	{
		return Collections.unmodifiableList(new ArrayList<>(goals));
	}

	public Goal focus()
	{
		return goals.isEmpty() ? null : goals.get(0);
	}

	public boolean isPinned(Goal goal)
	{
		return goals.contains(goal);
	}

	public void toggle(Goal goal)
	{
		if (!goals.remove(goal))
		{
			goals.add(goal);
		}
		changed(true);
	}

	public void makeFocus(Goal goal)
	{
		goals.remove(goal);
		goals.add(0, goal);
		changed(true);
	}

	/** Replaces the list from saved keys without saving it back. */
	public void load(List<String> keys)
	{
		goals.clear();
		if (keys != null)
		{
			for (String key : keys)
			{
				Goal goal = Goal.fromKey(key);
				if (goal != null && !goals.contains(goal))
				{
					goals.add(goal);
				}
			}
		}
		changed(false);
	}

	public List<String> keys()
	{
		List<String> keys = new ArrayList<>();
		for (Goal goal : goals)
		{
			keys.add(goal.key());
		}
		return keys;
	}

	private void changed(boolean save)
	{
		if (save)
		{
			saver.accept(keys());
		}
		for (Runnable listener : listeners)
		{
			listener.run();
		}
	}
}

package com.codex.navigator.core;

import java.util.Collections;
import java.util.List;

/** The planner's answer for one goal: how far along it is, the path, and the single next step. */
public final class Plan
{
	private final Goal goal;
	private final String title;
	private final String subtitle;
	private final boolean complete;
	private final double progress;
	private final List<Step> path;
	private final List<SkillGap> skills;
	private final Step next;
	private final int questsDone;
	private final int questsTotal;

	public Plan(Goal goal, String title, String subtitle, boolean complete, double progress, List<Step> path,
		List<SkillGap> skills, Step next, int questsDone, int questsTotal)
	{
		this.goal = goal;
		this.title = title;
		this.subtitle = subtitle;
		this.complete = complete;
		this.progress = progress;
		this.path = Collections.unmodifiableList(path);
		this.skills = Collections.unmodifiableList(skills);
		this.next = next;
		this.questsDone = questsDone;
		this.questsTotal = questsTotal;
	}

	public Goal getGoal()
	{
		return goal;
	}

	public String getTitle()
	{
		return title;
	}

	public String getSubtitle()
	{
		return subtitle;
	}

	public boolean isComplete()
	{
		return complete;
	}

	/** 0 to 1. */
	public double getProgress()
	{
		return progress;
	}

	/** Quests and checks in the order they can be done, prerequisites first. */
	public List<Step> getPath()
	{
		return path;
	}

	/** Every level the goal needs, unmet ones first. */
	public List<SkillGap> getSkills()
	{
		return skills;
	}

	/** The one thing to do next, or null when the goal is complete. */
	public Step getNext()
	{
		return next;
	}

	public int getQuestsDone()
	{
		return questsDone;
	}

	public int getQuestsTotal()
	{
		return questsTotal;
	}
}

package com.codex.navigator.core;

import com.codex.navigator.data.CodexData;
import com.codex.navigator.data.DiaryDef;
import com.codex.navigator.data.QuestDef;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * Works out the path to a goal from the bundled requirement data and an account snapshot.
 * Pure logic with no client access, so it is safe to run on any thread.
 */
public final class Planner
{
	private static final NumberFormat XP_FORMAT = NumberFormat.getIntegerInstance(Locale.ENGLISH);

	private final CodexData data;

	public Planner(CodexData data)
	{
		this.data = data;
	}

	public CodexData getData()
	{
		return data;
	}

	public static Skill skill(String name)
	{
		try
		{
			return Skill.valueOf(name.toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	public static String formatXp(int xp)
	{
		return XP_FORMAT.format(xp);
	}

	public Plan plan(Goal goal, AccountSnapshot account)
	{
		switch (goal.getType())
		{
			case QUEST:
				return planQuest(goal, account);
			case DIARY:
				return planDiary(goal, account);
			case QUEST_CAPE:
			default:
				return planQuestCape(goal, account);
		}
	}

	private Plan planQuest(Goal goal, AccountSnapshot account)
	{
		QuestDef quest = data.quest(goal.getName());
		if (quest == null)
		{
			return unknown(goal);
		}
		Set<String> closure = new LinkedHashSet<>();
		collect(quest.name, closure);
		String subtitle = (quest.miniquest ? "Miniquest" : quest.difficulty + " quest")
			+ (quest.points > 0 ? " · " + quest.points + " QP" : "");
		return build(goal, quest.name, subtitle, account.questDone(quest.name), closure,
			new EnumMap<>(Skill.class), 0, 0, false, account);
	}

	private Plan planDiary(Goal goal, AccountSnapshot account)
	{
		DiaryDef diary = data.diary(goal.getName());
		if (diary == null)
		{
			return unknown(goal);
		}
		Set<String> closure = new LinkedHashSet<>();
		for (String q : diary.quests)
		{
			collect(q, closure);
		}
		if (diary.allQuests)
		{
			for (QuestDef q : data.questCapeQuests())
			{
				collect(q.name, closure);
			}
		}
		Map<Skill, Integer> own = new EnumMap<>(Skill.class);
		addSkills(own, diary.skills);
		return build(goal, diary.name + " Diary", diary.area + " achievement diary", account.diaryDone(diary.name),
			closure, own, diary.questPoints, diary.combatLevel, true, account);
	}

	private Plan planQuestCape(Goal goal, AccountSnapshot account)
	{
		Set<String> closure = new LinkedHashSet<>();
		for (QuestDef q : data.questCapeQuests())
		{
			collect(q.name, closure);
		}
		boolean complete = true;
		for (QuestDef q : data.questCapeQuests())
		{
			complete &= account.questDone(q.name);
		}
		return build(goal, "Quest Point Cape", "Every quest in Gielinor", complete, closure,
			new EnumMap<>(Skill.class), 0, 0, false, account);
	}

	private Plan unknown(Goal goal)
	{
		Step check = new Step(Step.Kind.CHECK, Step.Status.UNKNOWN, goal.getName(), "Not in the Codex data yet", null, null);
		List<Step> path = new ArrayList<>();
		path.add(check);
		return new Plan(goal, goal.getName(), "Unknown goal", false, 0, path, new ArrayList<>(), check, 0, 0);
	}

	/** Adds a quest and everything it depends on, prerequisites first. */
	private void collect(String name, Set<String> closure)
	{
		collect(name, closure, new HashSet<>());
	}

	private void collect(String name, Set<String> closure, Set<String> visiting)
	{
		// The visiting set stops a cycle in the data from recursing forever.
		if (closure.contains(name) || !visiting.add(name))
		{
			return;
		}
		QuestDef quest = data.quest(name);
		if (quest != null)
		{
			for (String prereq : quest.prereqs)
			{
				collect(prereq, closure, visiting);
			}
		}
		closure.add(name);
	}

	private Plan build(Goal goal, String title, String subtitle, boolean complete, Set<String> closure,
		Map<Skill, Integer> targets, int questPointTarget, int combatTarget, boolean diaryTasks, AccountSnapshot account)
	{
		List<Step> path = new ArrayList<>();
		int questsDone = 0;
		int questsTotal = 0;
		double score = 0;
		int items = 0;

		for (String name : closure)
		{
			QuestDef quest = data.quest(name);
			if (quest == null)
			{
				path.add(new Step(Step.Kind.CHECK, Step.Status.UNKNOWN, name, "Check this one in game", null, null));
				continue;
			}
			questsTotal++;
			items++;
			Step step = questStep(quest, account);
			path.add(step);
			if (step.getStatus() == Step.Status.DONE)
			{
				questsDone++;
				score += 1;
				continue;
			}
			if (step.getStatus() == Step.Status.IN_PROGRESS)
			{
				score += 0.5;
			}
			addSkills(targets, quest.skills);
			questPointTarget = Math.max(questPointTarget, quest.questPoints);
			combatTarget = Math.max(combatTarget, quest.combatLevel);
		}

		List<SkillGap> skills = new ArrayList<>();
		for (Map.Entry<Skill, Integer> e : targets.entrySet())
		{
			SkillGap gap = new SkillGap(e.getKey(), account.level(e.getKey()), e.getValue(), account.xp(e.getKey()));
			skills.add(gap);
			score += gap.fraction();
			items++;
		}
		skills.sort(Comparator.comparing(SkillGap::isMet).thenComparingInt(SkillGap::xpToGo));

		if (questPointTarget > 0)
		{
			score += Math.min(1, account.getQuestPoints() / (double) questPointTarget);
			items++;
		}
		if (combatTarget > 0)
		{
			score += Math.min(1, account.getCombatLevel() / (double) combatTarget);
			items++;
		}

		double progress = complete ? 1 : items == 0 ? 0 : Math.min(0.99, score / items);
		Step next = complete ? null : next(path, skills, questPointTarget, combatTarget, diaryTasks, title, account);
		return new Plan(goal, title, subtitle, complete, progress, path, skills, next, questsDone, questsTotal);
	}

	private Step next(List<Step> path, List<SkillGap> skills, int questPointTarget, int combatTarget,
		boolean diaryTasks, String title, AccountSnapshot account)
	{
		for (Step step : path)
		{
			if (step.getStatus() == Step.Status.IN_PROGRESS)
			{
				return step;
			}
		}
		for (Step step : path)
		{
			if (step.getStatus() == Step.Status.READY)
			{
				return step;
			}
		}
		for (SkillGap gap : skills)
		{
			if (!gap.isMet())
			{
				return trainStep(gap);
			}
		}
		if (account.getQuestPoints() < questPointTarget)
		{
			int missing = questPointTarget - account.getQuestPoints();
			return new Step(Step.Kind.QUEST_POINTS, Step.Status.READY, "Earn " + missing + " more quest points",
				account.getQuestPoints() + " of " + questPointTarget + " QP", null, null);
		}
		if (account.getCombatLevel() < combatTarget)
		{
			return new Step(Step.Kind.COMBAT, Step.Status.READY, "Reach combat level " + combatTarget,
				"Currently " + account.getCombatLevel(), null, null);
		}
		for (Step step : path)
		{
			if (step.getStatus() == Step.Status.UNKNOWN)
			{
				return step;
			}
		}
		if (diaryTasks)
		{
			return new Step(Step.Kind.DIARY_TASKS, Step.Status.READY, "Finish the " + title + " tasks",
				"Every listed requirement is met", null, null);
		}
		return null;
	}

	public static Step trainStep(SkillGap gap)
	{
		String skillName = gap.getSkill().getName();
		return new Step(Step.Kind.TRAIN, Step.Status.READY, "Train " + skillName + " to " + gap.getTarget(),
			formatXp(gap.xpToGo()) + " xp to go", null, gap.getSkill());
	}

	public Step questStep(QuestDef quest, AccountSnapshot account)
	{
		QuestState state = account.quest(quest.name);
		if (state == QuestState.FINISHED)
		{
			return new Step(Step.Kind.QUEST, Step.Status.DONE, quest.name, "Complete", quest.name, null);
		}
		if (state == QuestState.IN_PROGRESS)
		{
			return new Step(Step.Kind.QUEST, Step.Status.IN_PROGRESS, quest.name, "In progress", quest.name, null);
		}
		List<String> blockers = blockers(quest, account);
		if (blockers.isEmpty())
		{
			return new Step(Step.Kind.QUEST, Step.Status.READY, quest.name, "Ready to start", quest.name, null);
		}
		String detail = "Needs " + blockers.get(0) + (blockers.size() > 1 ? " +" + (blockers.size() - 1) + " more" : "");
		return new Step(Step.Kind.QUEST, Step.Status.BLOCKED, quest.name, detail, quest.name, null);
	}

	/** Everything stopping a quest from being started right now, prerequisites first. */
	public List<String> blockers(QuestDef quest, AccountSnapshot account)
	{
		List<String> blockers = new ArrayList<>();
		for (String prereq : quest.prereqs)
		{
			if (!account.questDone(prereq))
			{
				blockers.add(prereq);
			}
		}
		for (Map.Entry<String, Integer> e : quest.skills.entrySet())
		{
			Skill skill = skill(e.getKey());
			if (skill != null && account.level(skill) < e.getValue())
			{
				blockers.add(skill.getName() + " " + e.getValue());
			}
		}
		if (account.getQuestPoints() < quest.questPoints)
		{
			blockers.add(quest.questPoints + " quest points");
		}
		if (account.getCombatLevel() < quest.combatLevel)
		{
			blockers.add("combat " + quest.combatLevel);
		}
		return blockers;
	}

	/** Level gaps for a quest whose prerequisite quests are all done, or null if a quest is still missing. */
	public List<SkillGap> levelGapsOnly(QuestDef quest, AccountSnapshot account)
	{
		for (String prereq : quest.prereqs)
		{
			if (!account.questDone(prereq))
			{
				return null;
			}
		}
		if (account.getQuestPoints() < quest.questPoints || account.getCombatLevel() < quest.combatLevel)
		{
			return null;
		}
		List<SkillGap> gaps = new ArrayList<>();
		for (Map.Entry<String, Integer> e : quest.skills.entrySet())
		{
			Skill skill = skill(e.getKey());
			if (skill != null && account.level(skill) < e.getValue())
			{
				gaps.add(new SkillGap(skill, account.level(skill), e.getValue(), account.xp(skill)));
			}
		}
		return gaps;
	}

	private static void addSkills(Map<Skill, Integer> targets, Map<String, Integer> skills)
	{
		for (Map.Entry<String, Integer> e : skills.entrySet())
		{
			Skill skill = skill(e.getKey());
			if (skill != null)
			{
				targets.merge(skill, e.getValue(), Math::max);
			}
		}
	}

	public static int countDone(Collection<QuestDef> quests, AccountSnapshot account)
	{
		int done = 0;
		for (QuestDef q : quests)
		{
			if (account.questDone(q.name))
			{
				done++;
			}
		}
		return done;
	}
}

package com.codex.navigator.core;

import com.codex.navigator.data.CodexData;
import com.codex.navigator.data.DiaryDef;
import com.codex.navigator.data.QuestDef;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.QuestState;

/** Picks what is worth doing right now when no goal is pinned, or alongside the pinned ones. */
public final class Recommender
{
	/** A quest suggestion with the reason it was chosen. */
	public static final class Pick
	{
		private final QuestDef quest;
		private final String reason;
		private final double score;
		private final List<SkillGap> gaps;

		Pick(QuestDef quest, String reason, double score, List<SkillGap> gaps)
		{
			this.quest = quest;
			this.reason = reason;
			this.score = score;
			this.gaps = gaps;
		}

		public QuestDef getQuest()
		{
			return quest;
		}

		public String getReason()
		{
			return reason;
		}

		public double getScore()
		{
			return score;
		}

		/** Levels still missing, for "almost there" picks; empty for quests that are ready. */
		public List<SkillGap> getGaps()
		{
			return gaps;
		}
	}

	private static final int ALMOST_THERE_LEVELS = 6;

	private final Planner planner;
	private final CodexData data;

	public Recommender(Planner planner)
	{
		this.planner = planner;
		this.data = planner.getData();
	}

	public List<QuestDef> inProgress(AccountSnapshot account)
	{
		List<QuestDef> list = new ArrayList<>();
		for (QuestDef q : data.quests())
		{
			if (account.quest(q.name) == QuestState.IN_PROGRESS)
			{
				list.add(q);
			}
		}
		return list;
	}

	/** Quests that can be started this minute, the ones that open the most doors first. */
	public List<Pick> readyNow(AccountSnapshot account, boolean includeMiniquests, int limit)
	{
		List<Pick> picks = new ArrayList<>();
		for (QuestDef q : data.quests())
		{
			if ((q.miniquest && !includeMiniquests) || account.quest(q.name) != QuestState.NOT_STARTED)
			{
				continue;
			}
			if (!planner.blockers(q, account).isEmpty())
			{
				continue;
			}
			int unlocks = data.unlockCount(q.name);
			double score = unlocks * 2.0 + q.points * 1.5 - q.difficultyRank() * 0.4 - (q.miniquest ? 1 : 0);
			picks.add(new Pick(q, reason(q, unlocks), score, new ArrayList<>()));
		}
		picks.sort(Comparator.comparingDouble(Pick::getScore).reversed());
		return picks.size() > limit ? new ArrayList<>(picks.subList(0, limit)) : picks;
	}

	/** Quests held back only by a few levels, closest first. */
	public List<Pick> almostThere(AccountSnapshot account, boolean includeMiniquests, int limit)
	{
		List<Pick> picks = new ArrayList<>();
		for (QuestDef q : data.quests())
		{
			if ((q.miniquest && !includeMiniquests) || account.quest(q.name) != QuestState.NOT_STARTED)
			{
				continue;
			}
			List<SkillGap> gaps = planner.levelGapsOnly(q, account);
			if (gaps == null || gaps.isEmpty())
			{
				continue;
			}
			int levels = 0;
			int xp = 0;
			for (SkillGap gap : gaps)
			{
				levels += gap.getTarget() - gap.getCurrent();
				xp += gap.xpToGo();
			}
			if (levels > ALMOST_THERE_LEVELS)
			{
				continue;
			}
			StringBuilder reason = new StringBuilder();
			for (SkillGap gap : gaps)
			{
				if (reason.length() > 0)
				{
					reason.append(", ");
				}
				reason.append(gap.getSkill().getName()).append(' ').append(gap.getCurrent()).append(" to ").append(gap.getTarget());
			}
			picks.add(new Pick(q, reason.toString(), -xp, gaps));
		}
		picks.sort(Comparator.comparingDouble(Pick::getScore).reversed());
		return picks.size() > limit ? new ArrayList<>(picks.subList(0, limit)) : picks;
	}

	/** Unfinished diary tiers, the closest to done first. */
	public List<Plan> closestDiaries(AccountSnapshot account, int limit)
	{
		List<Plan> plans = new ArrayList<>();
		for (DiaryDef d : data.diaries())
		{
			if (!account.diaryDone(d.name))
			{
				plans.add(planner.plan(Goal.diary(d.name), account));
			}
		}
		plans.sort(Comparator.comparingDouble(Plan::getProgress).reversed());
		return plans.size() > limit ? new ArrayList<>(plans.subList(0, limit)) : plans;
	}

	private static String reason(QuestDef q, int unlocks)
	{
		if (unlocks >= 3)
		{
			return "Opens " + unlocks + " more";
		}
		if (q.points >= 2)
		{
			return "+" + q.points + " QP";
		}
		return null;
	}
}

package com.codex.navigator.core;

import net.runelite.api.Experience;
import net.runelite.api.Skill;

/** A level a goal needs, and how far the account is from it. */
public final class SkillGap
{
	private final Skill skill;
	private final int current;
	private final int target;
	private final int currentXp;

	public SkillGap(Skill skill, int current, int target, int currentXp)
	{
		this.skill = skill;
		this.current = current;
		this.target = target;
		this.currentXp = currentXp;
	}

	public Skill getSkill()
	{
		return skill;
	}

	public int getCurrent()
	{
		return current;
	}

	public int getTarget()
	{
		return target;
	}

	public boolean isMet()
	{
		return current >= target;
	}

	public int xpToGo()
	{
		return Math.max(0, Experience.getXpForLevel(target) - currentXp);
	}

	/** Progress toward the target measured in experience, so 98 of 99 reads as about 90%. */
	public double fraction()
	{
		if (isMet())
		{
			return 1;
		}
		int needed = Experience.getXpForLevel(target);
		return needed <= 0 ? 1 : Math.min(1, currentXp / (double) needed);
	}
}

package com.codex.navigator.core;

import net.runelite.api.Skill;

/** One line on a goal's path: a quest to do, a level to reach, or something to check by hand. */
public final class Step
{
	public enum Kind
	{
		QUEST,
		TRAIN,
		QUEST_POINTS,
		COMBAT,
		DIARY_TASKS,
		CHECK
	}

	public enum Status
	{
		DONE,
		IN_PROGRESS,
		READY,
		BLOCKED,
		UNKNOWN
	}

	private final Kind kind;
	private final Status status;
	private final String title;
	private final String detail;
	private final String quest;
	private final Skill skill;

	public Step(Kind kind, Status status, String title, String detail, String quest, Skill skill)
	{
		this.kind = kind;
		this.status = status;
		this.title = title;
		this.detail = detail;
		this.quest = quest;
		this.skill = skill;
	}

	public Kind getKind()
	{
		return kind;
	}

	public Status getStatus()
	{
		return status;
	}

	public String getTitle()
	{
		return title;
	}

	/** Why the step is blocked, or what it involves; may be empty. */
	public String getDetail()
	{
		return detail;
	}

	/** The quest this step is about, for quest steps. */
	public String getQuest()
	{
		return quest;
	}

	/** The skill to train, for training steps. */
	public Skill getSkill()
	{
		return skill;
	}
}

package com.codex.navigator.data;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The bundled requirement data: quests, diaries and combat achievement tier sizes,
 * plus a reverse index of how much each quest unlocks.
 */
public final class CodexData
{
	public static final String[] COMBAT_ACHIEVEMENT_TIERS = {"Easy", "Medium", "Hard", "Elite", "Master", "Grandmaster"};

	private static final class Raw
	{
		List<QuestDef> quests;
		List<DiaryDef> diaries;
		Map<String, Integer> combatAchievementTasks;
	}

	private final Map<String, QuestDef> quests = new LinkedHashMap<>();
	private final Map<String, DiaryDef> diaries = new LinkedHashMap<>();
	private final Map<String, Integer> combatAchievementTasks;
	private final Map<String, Integer> unlocks = new HashMap<>();

	public CodexData(List<QuestDef> questList, List<DiaryDef> diaryList, Map<String, Integer> caTasks)
	{
		for (QuestDef q : questList)
		{
			quests.put(q.name, q);
		}
		for (DiaryDef d : diaryList)
		{
			diaries.put(d.name, d);
		}
		combatAchievementTasks = caTasks == null ? Collections.emptyMap() : caTasks;
		indexUnlocks();
	}

	public static CodexData load(Gson gson)
	{
		try (InputStream in = CodexData.class.getResourceAsStream("/com/codex/navigator/codex-data.json"))
		{
			if (in == null)
			{
				throw new IllegalStateException("codex-data.json is missing from the plugin jar");
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				Raw raw = gson.fromJson(reader, Raw.class);
				return new CodexData(raw.quests, raw.diaries, raw.combatAchievementTasks);
			}
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Could not read codex-data.json", e);
		}
	}

	/** Counts, for every quest, how many quests and diaries need it somewhere down their chain. */
	private void indexUnlocks()
	{
		Map<String, Set<String>> dependents = new HashMap<>();
		for (QuestDef q : quests.values())
		{
			for (String p : q.prereqs)
			{
				dependents.computeIfAbsent(p, k -> new HashSet<>()).add("q:" + q.name);
			}
		}
		for (DiaryDef d : diaries.values())
		{
			for (String p : d.quests)
			{
				dependents.computeIfAbsent(p, k -> new HashSet<>()).add("d:" + d.name);
			}
		}
		for (String name : quests.keySet())
		{
			Set<String> seen = new HashSet<>();
			Deque<String> queue = new ArrayDeque<>();
			queue.add(name);
			while (!queue.isEmpty())
			{
				String current = queue.poll();
				for (String dep : dependents.getOrDefault(current, Collections.emptySet()))
				{
					if (seen.add(dep) && dep.startsWith("q:"))
					{
						queue.add(dep.substring(2));
					}
				}
			}
			unlocks.put(name, seen.size());
		}
	}

	public Collection<QuestDef> quests()
	{
		return quests.values();
	}

	public Collection<DiaryDef> diaries()
	{
		return diaries.values();
	}

	public QuestDef quest(String name)
	{
		return quests.get(name);
	}

	public DiaryDef diary(String name)
	{
		return diaries.get(name);
	}

	public int unlockCount(String quest)
	{
		return unlocks.getOrDefault(quest, 0);
	}

	public int combatAchievementTasks(String tier)
	{
		return combatAchievementTasks.getOrDefault(tier, 0);
	}

	public List<QuestDef> questCapeQuests()
	{
		List<QuestDef> list = new ArrayList<>();
		for (QuestDef q : quests.values())
		{
			if (!q.miniquest)
			{
				list.add(q);
			}
		}
		return list;
	}

	public int totalQuestPoints()
	{
		int total = 0;
		for (QuestDef q : quests.values())
		{
			total += q.points;
		}
		return total;
	}
}

