package com.codex.navigator.overlay;

import com.codex.navigator.ui.Theme;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small gilt plaque in the game view: the focus goal, a progress rule and the next step.
 * It reads a snapshot the plugin prepares, so rendering never touches game state.
 */
public class FocusOverlay extends Overlay
{
	private static final int WIDTH = 176;
	private static final int PAD = 8;

	/** What the plaque shows; the plugin swaps in a new one when anything changes. */
	public static final class View
	{
		final String label;
		final String title;
		/** 0 to 1, or negative to hide the percentage for a suggestion. */
		final double progress;
		final String step;

		public View(String label, String title, double progress, String step)
		{
			this.label = label;
			this.title = title;
			this.progress = progress;
			this.step = step;
		}
	}

	private volatile View view;

	public FocusOverlay()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	public void setView(View view)
	{
		this.view = view;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		View v = view;
		if (v == null)
		{
			return null;
		}
		Theme.smooth(g);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();

		String title = clip(v.title, bold, WIDTH - PAD * 2);
		String step = v.step == null ? null : clip(v.step, small, WIDTH - PAD * 2);
		int height = PAD + small.getHeight() + bold.getHeight() + 8 + (step != null ? small.getHeight() + 2 : 0) + PAD - 2;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 10, 10);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 230), 0, height, Theme.alpha(Theme.INK_DEEP, 230)));
		g.fill(shape);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 150));
		g.draw(shape);

		int y = PAD + small.getAscent();
		g.setFont(Theme.small());
		shadow(g, v.label, PAD, y, Theme.GOLD);
		if (v.progress >= 0)
		{
			String pct = Math.round(v.progress * 100) + "%";
			shadow(g, pct, WIDTH - PAD - small.stringWidth(pct), y, Theme.progressColor(v.progress));
		}

		y += bold.getAscent() + 2;
		g.setFont(Theme.title());
		shadow(g, title, PAD, y, Theme.GOLD_BRIGHT);

		y += 5;
		int barW = WIDTH - PAD * 2;
		g.setColor(Theme.INK_DEEP);
		g.fillRoundRect(PAD, y, barW, 3, 3, 3);
		int fill = v.progress < 0 ? 0 : (int) Math.round(barW * Math.min(1, v.progress));
		if (fill > 0)
		{
			g.setPaint(new GradientPaint(PAD, 0, Theme.progressColor(0), PAD + barW, 0, Theme.progressColor(1)));
			g.fillRoundRect(PAD, y, fill, 3, 3, 3);
		}

		if (step != null)
		{
			y += 4 + small.getAscent() + 2;
			g.setFont(Theme.small());
			shadow(g, step, PAD, y, Theme.TEXT);
		}
		return new Dimension(WIDTH, height);
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String clip(String text, FontMetrics fm, int width)
	{
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String ellipsis = "...";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > width)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}
}

package com.codex.navigator.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.navigator.ui;

import com.codex.navigator.core.AccountSnapshot;
import com.codex.navigator.core.Goal;
import com.codex.navigator.core.Plan;
import com.codex.navigator.core.Step;
import com.codex.navigator.data.CodexData;
import com.codex.navigator.data.DiaryDef;
import com.codex.navigator.data.QuestDef;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.components.IconTextField;

/** Everything in the Codex, searchable: quests, diaries and combat achievement tiers. */
final class AtlasView extends JPanel
{
	private static final String[] FILTERS = {"All", "Ready", "To do", "Done"};

	private final Navigation nav;
	private final IconTextField search = new IconTextField();
	private final Segmented kind = new Segmented(false, "Quests", "Diaries", "Combat");
	private final Segmented filter = new Segmented(false, FILTERS);
	private final JScrollPane scroll;

	AtlasView(Navigation nav)
	{
		super(new BorderLayout());
		this.nav = nav;
		setOpaque(false);

		StackPanel controls = new StackPanel(6, 8);
		controls.setBorder(new EmptyBorder(8, 8, 4, 8));
		search.setIcon(IconTextField.Icon.SEARCH);
		search.setBackground(Theme.INK_DEEP);
		search.setHoverBackgroundColor(Theme.CARD);
		search.setPreferredSize(new java.awt.Dimension(10, 28));
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rebuild();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rebuild();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rebuild();
			}
		});
		search.addClearListener(this::rebuild);
		controls.add(search);
		controls.add(kind);
		controls.add(filter);
		kind.onChange(i ->
		{
			filter.setVisible(i == 0);
			search.setVisible(i != 2);
			controls.revalidate();
			rebuild();
		});
		filter.onChange(i -> rebuild());
		add(controls, BorderLayout.NORTH);

		scroll = NavigatorPanel.scroller(new StackPanel(6, 8));
		add(scroll, BorderLayout.CENTER);
	}

	void rebuild()
	{
		int position = scroll.getVerticalScrollBar().getValue();
		StackPanel list;
		switch (kind.getSelected())
		{
			case 1:
				list = diaries();
				break;
			case 2:
				list = combat();
				break;
			default:
				list = quests();
		}
		scroll.setViewportView(list);
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	private String query()
	{
		return search.getText() == null ? "" : search.getText().trim().toLowerCase(Locale.ROOT);
	}

	private StackPanel quests()
	{
		StackPanel stack = new StackPanel(4, 8);
		AccountSnapshot account = nav.account();
		String q = query();
		List<Step> steps = new ArrayList<>();
		Map<String, QuestDef> defs = new LinkedHashMap<>();
		for (QuestDef quest : nav.planner().getData().quests())
		{
			if (quest.miniquest && !nav.includeMiniquests())
			{
				continue;
			}
			if (!q.isEmpty() && !quest.name.toLowerCase(Locale.ROOT).contains(q)
				&& (quest.series == null || !quest.series.toLowerCase(Locale.ROOT).contains(q)))
			{
				continue;
			}
			Step step = nav.planner().questStep(quest, account);
			if (!matches(step.getStatus()))
			{
				continue;
			}
			steps.add(step);
			defs.put(quest.name, quest);
		}
		steps.sort(Comparator.comparingInt((Step s) -> order(s.getStatus())).thenComparing(Step::getTitle));
		stack.add(new SectionHeader(FILTERS[filter.getSelected()] + " quests", String.valueOf(steps.size())));
		for (Step step : steps)
		{
			QuestDef quest = defs.get(step.getTitle());
			Goal goal = Goal.quest(quest.name);
			String detail = step.getStatus() == Step.Status.BLOCKED ? step.getDetail() : CompassView.subtitle(quest);
			stack.add(Row.of(step.getStatus(), quest.name, detail,
				nav.goals().isPinned(goal) ? new Pill("Pinned", Theme.GOLD) : null, null, () -> nav.open(goal)));
		}
		if (steps.isEmpty())
		{
			stack.add(GoalCard.hint("Nothing matches. Try another word or filter."));
		}
		return stack;
	}

	private boolean matches(Step.Status status)
	{
		switch (filter.getSelected())
		{
			case 1:
				return status == Step.Status.READY || status == Step.Status.IN_PROGRESS;
			case 2:
				return status != Step.Status.DONE;
			case 3:
				return status == Step.Status.DONE;
			default:
				return true;
		}
	}

	private static int order(Step.Status status)
	{
		switch (status)
		{
			case IN_PROGRESS:
				return 0;
			case READY:
				return 1;
			case BLOCKED:
				return 2;
			case DONE:
				return 4;
			default:
				return 3;
		}
	}

	private StackPanel diaries()
	{
		StackPanel stack = new StackPanel(6, 8);
		AccountSnapshot account = nav.account();
		String q = query();
		Map<String, List<DiaryDef>> areas = new LinkedHashMap<>();
		for (DiaryDef d : nav.planner().getData().diaries())
		{
			if (q.isEmpty() || d.area.toLowerCase(Locale.ROOT).contains(q))
			{
				areas.computeIfAbsent(d.area, k -> new ArrayList<>()).add(d);
			}
		}
		stack.add(new SectionHeader("Achievement diaries", account.diariesCompleted() + "/" + nav.planner().getData().diaries().size()));
		List<String> names = new ArrayList<>(areas.keySet());
		names.sort(String::compareTo);
		for (String area : names)
		{
			List<DiaryDef> tiers = areas.get(area);
			tiers.sort(Comparator.comparingInt(DiaryDef::tierRank));
			Card card = new Card(new BorderLayout(0, 6));
			int done = 0;
			JPanel chips = new JPanel(new GridLayout(1, tiers.size(), 4, 0));
			chips.setOpaque(false);
			for (DiaryDef d : tiers)
			{
				Goal goal = Goal.diary(d.name);
				Plan plan = nav.planner().plan(goal, account);
				Step.Status status = plan.isComplete() ? Step.Status.DONE
					: plan.getNext() != null && plan.getNext().getKind() == Step.Kind.DIARY_TASKS ? Step.Status.READY : Step.Status.BLOCKED;
				done += plan.isComplete() ? 1 : 0;
				TierChip chip = new TierChip(d.tier.equals("Medium") ? "Med" : d.tier, status, plan.getProgress(), () -> nav.open(goal));
				chip.setToolTipText(d.name + (plan.getNext() != null ? ": " + plan.getNext().getTitle() : ""));
				chips.add(chip);
			}
			JPanel title = new JPanel(new BorderLayout());
			title.setOpaque(false);
			title.add(Ui.label(area, Theme.title(), Theme.GOLD_BRIGHT), BorderLayout.WEST);
			title.add(Ui.label(done + "/" + tiers.size(), Theme.small(), done == tiers.size() ? Theme.GREEN : Theme.TEXT_MUTED),
				BorderLayout.EAST);
			card.add(title, BorderLayout.NORTH);
			card.add(chips, BorderLayout.CENTER);
			stack.add(card);
		}
		return stack;
	}

	private StackPanel combat()
	{
		StackPanel stack = new StackPanel(6, 8);
		AccountSnapshot account = nav.account();
		CodexData data = nav.planner().getData();
		stack.add(new SectionHeader("Combat achievements", account.getCombatAchievementPoints() + " pts"));
		for (String tier : CodexData.COMBAT_ACHIEVEMENT_TIERS)
		{
			int total = data.combatAchievementTasks(tier);
			int done = Math.min(total, account.combatAchievementsDone(tier));
			Card card = new Card(new BorderLayout(0, 5));
			JPanel line = new JPanel(new BorderLayout());
			line.setOpaque(false);
			line.add(Ui.label(tier, Theme.title(), done >= total && total > 0 ? Theme.GREEN : Theme.GOLD_BRIGHT), BorderLayout.WEST);
			line.add(Ui.label(done + " / " + total + " tasks", Theme.small(), Theme.TEXT_MUTED), BorderLayout.EAST);
			card.add(line, BorderLayout.NORTH);
			ProgressBar bar = new ProgressBar(5);
			bar.setProgress(total == 0 ? 0 : done / (double) total, total > 0 && done >= total, true);
			card.add(bar, BorderLayout.CENTER);
			stack.add(card);
		}
		stack.add(GoalCard.hint("Task counts come from the game. The in-game Combat Achievements window has each task's details."));
		return stack;
	}
}

package com.codex.navigator.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.navigator.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.navigator.ui;

import com.codex.navigator.core.AccountSnapshot;
import com.codex.navigator.core.Goal;
import com.codex.navigator.core.Plan;
import com.codex.navigator.core.Recommender;
import com.codex.navigator.core.Step;
import com.codex.navigator.data.QuestDef;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The home view: your focus, then what is worth doing right now. */
final class CompassView
{
	private CompassView()
	{
	}

	static StackPanel build(Navigation nav)
	{
		StackPanel stack = new StackPanel(6, 8);
		AccountSnapshot account = nav.account();
		if (!account.isLoggedIn())
		{
			stack.add(welcome(nav));
			return stack;
		}

		Goal focus = nav.goals().focus();
		if (focus != null)
		{
			Plan plan = nav.planner().plan(focus, account);
			stack.add(GoalCard.build(nav, plan, true, false));
		}
		else
		{
			stack.add(choose(nav));
		}

		Recommender rec = nav.recommender();
		List<QuestDef> active = rec.inProgress(account);
		if (!active.isEmpty())
		{
			stack.add(new SectionHeader("In progress", String.valueOf(active.size())));
			for (QuestDef q : active)
			{
				stack.add(Row.of(Step.Status.IN_PROGRESS, q.name, q.difficulty == null ? "" : q.difficulty, null, null,
					() -> nav.open(Goal.quest(q.name))));
			}
		}

		List<Recommender.Pick> ready = rec.readyNow(account, nav.includeMiniquests(), 6);
		if (!ready.isEmpty())
		{
			stack.add(new SectionHeader("Ready now"));
			for (Recommender.Pick pick : ready)
			{
				QuestDef q = pick.getQuest();
				stack.add(Row.of(Step.Status.READY, q.name, subtitle(q), pick.getReason() == null ? null : new Pill(pick.getReason(), Theme.TEAL), null,
					() -> nav.open(Goal.quest(q.name))));
			}
		}

		List<Recommender.Pick> almost = rec.almostThere(account, nav.includeMiniquests(), 4);
		if (!almost.isEmpty())
		{
			stack.add(new SectionHeader("Almost there"));
			for (Recommender.Pick pick : almost)
			{
				QuestDef q = pick.getQuest();
				stack.add(Row.of(Step.Status.BLOCKED, q.name, pick.getReason(), null, null,
					() -> nav.open(Goal.quest(q.name))));
			}
		}

		List<Plan> diaries = rec.closestDiaries(account, 3);
		if (!diaries.isEmpty())
		{
			stack.add(new SectionHeader("Closest diaries"));
			for (Plan plan : diaries)
			{
				stack.add(diaryRow(nav, plan));
			}
		}
		return stack;
	}

	static String subtitle(QuestDef q)
	{
		String kind = q.miniquest ? "Miniquest" : q.difficulty;
		return q.points > 0 ? kind + "  ·  " + q.points + " QP" : kind;
	}

	private static Card diaryRow(Navigation nav, Plan plan)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.setBorder(new EmptyBorder(7, 10, 8, 10));
		JPanel line = new JPanel(new BorderLayout());
		line.setOpaque(false);
		line.add(Ui.label(plan.getTitle().replace(" Diary", ""), Theme.body(), Theme.TEXT), BorderLayout.WEST);
		line.add(Ui.label(Math.round(plan.getProgress() * 100) + "%", Theme.small(), Theme.TEXT_MUTED), BorderLayout.EAST);
		card.add(line, BorderLayout.NORTH);
		ProgressBar bar = new ProgressBar(4);
		bar.setProgress(plan.getProgress(), false, false);
		card.add(bar, BorderLayout.CENTER);
		Step next = plan.getNext();
		if (next != null)
		{
			card.add(Ui.label("Next: " + next.getTitle(), Theme.small(), Theme.TEXT_MUTED), BorderLayout.SOUTH);
		}
		card.onClick(() -> nav.open(plan.getGoal()));
		return card;
	}

	private static Card choose(Navigation nav)
	{
		Card card = new Card(new BorderLayout(0, 6));
		card.setBorder(new EmptyBorder(10, 10, 10, 10));
		card.highlighted(true);
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(Ui.label("SET A HEADING", Theme.small(), Theme.GOLD));
		text.add(Ui.wrapped("Pin any quest or diary and the Codex charts the whole path to it.", Theme.body(), Theme.TEXT, 168));
		card.add(text, BorderLayout.CENTER);
		JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		actions.setOpaque(false);
		actions.add(new CodexButton("Browse the Atlas", true, () -> nav.showTab(2)));
		actions.add(new JPanel()
		{
			{
				setOpaque(false);
				setPreferredSize(new java.awt.Dimension(6, 1));
			}
		});
		actions.add(new CodexButton("Quest cape", false, () -> nav.goals().toggle(Goal.QUEST_CAPE)));
		card.add(actions, BorderLayout.SOUTH);
		return card;
	}

	private static Card welcome(Navigation nav)
	{
		Card card = new Card(new BorderLayout(0, 6));
		card.setBorder(new EmptyBorder(14, 12, 14, 12));
		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(Ui.label("THE CODEX AWAITS", Theme.small(), Theme.GOLD));
		text.add(Ui.wrapped("Log in and the Codex reads your quests, diaries, levels and combat tasks straight from the game.",
			Theme.body(), Theme.TEXT, 168));
		text.add(Ui.wrapped("Nothing leaves your computer.", Theme.small(), Theme.TEXT_MUTED, 168));
		card.add(text, BorderLayout.CENTER);
		return card;
	}
}

package com.codex.navigator.ui;

import com.codex.navigator.core.AccountSnapshot;
import com.codex.navigator.data.CodexData;
import com.codex.navigator.data.QuestDef;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.geom.Path2D;
import java.text.NumberFormat;
import java.util.Locale;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * The account crest at the top of the panel: one ring for the whole account and
 * three ledgers beneath the name for quests, diaries and combat tasks.
 */
public class CrestHeader extends JPanel
{
	private static final NumberFormat NUMBER = NumberFormat.getIntegerInstance(Locale.ENGLISH);

	private final ProgressRing ring = new ProgressRing(60, 6f);
	private final JLabel name = Ui.label("Codex", Theme.title(), Theme.GOLD_BRIGHT);
	private final JLabel summary = Ui.label("Log in to open your codex", Theme.small(), Theme.TEXT_MUTED);
	private final Ledger quests = new Ledger("Quests");
	private final Ledger diaries = new Ledger("Diaries");
	private final Ledger combat = new Ledger("Combat tasks");

	public CrestHeader()
	{
		super(new BorderLayout(10, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		JPanel ringHolder = new JPanel(new BorderLayout());
		ringHolder.setOpaque(false);
		ringHolder.add(ring, BorderLayout.NORTH);
		add(ringHolder, BorderLayout.WEST);

		JPanel right = new JPanel();
		right.setOpaque(false);
		right.setLayout(new BoxLayout(right, BoxLayout.Y_AXIS));
		name.setAlignmentX(LEFT_ALIGNMENT);
		summary.setAlignmentX(LEFT_ALIGNMENT);
		right.add(name);
		right.add(summary);

		JPanel ledgers = new JPanel(new GridLayout(3, 1, 0, 2));
		ledgers.setOpaque(false);
		ledgers.setBorder(new EmptyBorder(4, 0, 0, 0));
		ledgers.add(quests);
		ledgers.add(diaries);
		ledgers.add(combat);
		ledgers.setAlignmentX(LEFT_ALIGNMENT);
		right.add(ledgers);
		add(right, BorderLayout.CENTER);
	}

	public void update(AccountSnapshot account, CodexData data)
	{
		int questTotal = 0;
		int questDone = 0;
		for (QuestDef q : data.quests())
		{
			questTotal++;
			if (account.questDone(q.name))
			{
				questDone++;
			}
		}
		int diaryTotal = data.diaries().size();
		int diaryDone = account.diariesCompleted();
		int caTotal = 0;
		int caDone = 0;
		for (String tier : CodexData.COMBAT_ACHIEVEMENT_TIERS)
		{
			caTotal += data.combatAchievementTasks(tier);
			caDone += Math.min(account.combatAchievementsDone(tier), data.combatAchievementTasks(tier));
		}

		boolean in = account.isLoggedIn();
		name.setText(in && account.getPlayerName() != null ? account.getPlayerName() : "Codex");
		summary.setText(in
			? "Total " + NUMBER.format(account.totalLevel()) + "  ·  Combat " + account.getCombatLevel()
			: "Log in to open your codex");
		quests.set(questDone, questTotal);
		diaries.set(diaryDone, diaryTotal);
		combat.set(caDone, caTotal);

		double overall = !in ? 0 : (ratio(questDone, questTotal) + ratio(diaryDone, diaryTotal) + ratio(caDone, caTotal)) / 3;
		ring.setProgress(overall, in && overall >= 1, true);
		ring.setToolTipText("Account completion across quests, diaries and combat achievement tasks");
	}

	private static double ratio(int done, int total)
	{
		return total <= 0 ? 0 : done / (double) total;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.16), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// Gilt rule along the bottom with a small diamond at its centre.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
		super.paintComponent(graphics);
	}

	/** One labelled count with a hairline bar under it. */
	private static final class Ledger extends JPanel
	{
		private final JLabel count = Ui.label("-", Theme.small(), Theme.TEXT);
		private final ProgressBar bar = new ProgressBar(3);

		Ledger(String label)
		{
			super(new BorderLayout(0, 1));
			setOpaque(false);
			JPanel line = new JPanel(new BorderLayout());
			line.setOpaque(false);
			line.add(Ui.label(label, Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
			line.add(count, BorderLayout.EAST);
			add(line, BorderLayout.CENTER);
			add(bar, BorderLayout.SOUTH);
			setPreferredSize(new Dimension(10, 17));
		}

		void set(int done, int total)
		{
			count.setText(done + "/" + total);
			bar.setProgress(ratio(done, total), total > 0 && done >= total, true);
		}
	}
}

package com.codex.navigator.ui;

import com.codex.navigator.core.Goal;
import com.codex.navigator.core.Plan;
import com.codex.navigator.core.SkillGap;
import com.codex.navigator.core.Step;
import java.awt.BorderLayout;
import java.awt.Cursor;
import java.awt.FlowLayout;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/** One goal laid open: progress, the next step, every level it needs and the full path. */
final class DetailView
{
	private DetailView()
	{
	}

	static StackPanel build(Navigation nav, Goal goal, boolean showCompleted, Runnable back, Runnable toggleCompleted)
	{
		Plan plan = nav.planner().plan(goal, nav.account());
		StackPanel stack = new StackPanel(6, 8);

		JLabel backLink = Ui.label("<  Back", Theme.small(), Theme.GOLD);
		backLink.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		backLink.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseReleased(MouseEvent e)
			{
				back.run();
			}
		});
		JPanel backRow = new JPanel(new BorderLayout());
		backRow.setOpaque(false);
		backRow.add(backLink, BorderLayout.WEST);
		stack.add(backRow);

		stack.add(hero(nav, plan));

		if (!plan.getSkills().isEmpty())
		{
			int unmet = 0;
			for (SkillGap gap : plan.getSkills())
			{
				unmet += gap.isMet() ? 0 : 1;
			}
			stack.add(new SectionHeader("Levels", unmet == 0 ? "all met" : unmet + " to train"));
			Card skills = new Card(new BorderLayout());
			StackPanel list = new StackPanel(5, 0);
			for (SkillGap gap : plan.getSkills())
			{
				list.add(skillRow(nav, gap));
			}
			skills.add(list, BorderLayout.CENTER);
			stack.add(skills);
		}

		List<Step> path = plan.getPath();
		if (!path.isEmpty() && !(path.size() == 1 && goal.getType() == Goal.Type.QUEST))
		{
			List<Step> shown = new ArrayList<>();
			int done = 0;
			for (Step step : path)
			{
				if (step.getStatus() == Step.Status.DONE)
				{
					done++;
					if (!showCompleted)
					{
						continue;
					}
				}
				shown.add(step);
			}
			stack.add(new SectionHeader("Path", plan.getQuestsDone() + "/" + plan.getQuestsTotal()));
			Card pathCard = new Card(new BorderLayout());
			pathCard.setBorder(new EmptyBorder(6, 8, 6, 8));
			StackPanel rows = new StackPanel(0, 0);
			if (done > 0)
			{
				JLabel toggle = Ui.label((showCompleted ? "Hide " : "Show ") + done + " completed", Theme.small(), Theme.GOLD);
				toggle.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
				toggle.setBorder(new EmptyBorder(2, 2, 6, 0));
				toggle.addMouseListener(new MouseAdapter()
				{
					@Override
					public void mouseReleased(MouseEvent e)
					{
						toggleCompleted.run();
					}
				});
				rows.add(toggle);
			}
			for (int i = 0; i < shown.size(); i++)
			{
				Step step = shown.get(i);
				Runnable open = step.getQuest() != null && !step.getQuest().equals(goal.getName())
					? () -> nav.open(Goal.quest(step.getQuest())) : null;
				rows.add(new TimelineRow(step, i == 0, i == shown.size() - 1, open));
			}
			if (shown.isEmpty())
			{
				rows.add(Ui.label("Every quest on this path is done.", Theme.small(), Theme.GREEN));
			}
			pathCard.add(rows, BorderLayout.CENTER);
			stack.add(pathCard);
		}
		return stack;
	}

	private static Card hero(Navigation nav, Plan plan)
	{
		Card card = new Card(new BorderLayout(0, 10));
		card.setBorder(new EmptyBorder(12, 10, 10, 10));
		card.highlighted(true);

		JPanel titles = new JPanel();
		titles.setOpaque(false);
		titles.setLayout(new BoxLayout(titles, BoxLayout.Y_AXIS));
		titles.add(Ui.wrapped(plan.getTitle(), Theme.title(), Theme.GOLD_BRIGHT, 168));
		titles.add(Ui.wrapped(plan.getSubtitle(), Theme.small(), Theme.TEXT_MUTED, 168));
		card.add(titles, BorderLayout.NORTH);

		JPanel middle = new JPanel(new BorderLayout(10, 0));
		middle.setOpaque(false);
		ProgressRing ring = new ProgressRing(74, 7f);
		ring.setProgress(plan.getProgress(), plan.isComplete(), true);
		if (plan.getQuestsTotal() > 1)
		{
			ring.setCaption(plan.getQuestsDone() + "/" + plan.getQuestsTotal());
		}
		JPanel ringHolder = new JPanel(new BorderLayout());
		ringHolder.setOpaque(false);
		ringHolder.add(ring, BorderLayout.NORTH);
		middle.add(ringHolder, BorderLayout.WEST);

		JPanel actions = new JPanel();
		actions.setOpaque(false);
		actions.setLayout(new BoxLayout(actions, BoxLayout.Y_AXIS));
		boolean pinned = nav.goals().isPinned(plan.getGoal());
		boolean focus = plan.getGoal().equals(nav.goals().focus());
		actions.add(Ui.label(focus ? "Your focus" : pinned ? "Pinned" : "Not pinned", Theme.small(),
			focus ? Theme.GOLD : Theme.TEXT_MUTED));
		actions.add(spacer(6));
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 4));
		buttons.setOpaque(false);
		buttons.setLayout(new BoxLayout(buttons, BoxLayout.Y_AXIS));
		CodexButton pin = new CodexButton(pinned ? "Unpin" : "Pin goal", !pinned, () -> nav.goals().toggle(plan.getGoal()));
		pin.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		buttons.add(pin);
		if (pinned && !focus)
		{
			buttons.add(spacer(4));
			CodexButton makeFocus = new CodexButton("Make focus", true, () -> nav.goals().makeFocus(plan.getGoal()));
			makeFocus.setAlignmentX(JPanel.LEFT_ALIGNMENT);
			buttons.add(makeFocus);
		}
		buttons.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		actions.add(buttons);
		middle.add(actions, BorderLayout.CENTER);
		card.add(middle, BorderLayout.CENTER);

		card.add(new NextStepBox(plan.getNext(), 152), BorderLayout.SOUTH);
		return card;
	}

	private static JPanel skillRow(Navigation nav, SkillGap gap)
	{
		JPanel row = new JPanel(new BorderLayout(6, 2));
		row.setOpaque(false);
		BufferedImage icon = nav.skillIcon(gap.getSkill());
		JLabel iconLabel = new JLabel();
		if (icon != null)
		{
			iconLabel.setIcon(new ImageIcon(icon));
		}
		iconLabel.setPreferredSize(new java.awt.Dimension(18, 18));
		row.add(iconLabel, BorderLayout.WEST);

		JPanel right = new JPanel(new BorderLayout(0, 2));
		right.setOpaque(false);
		JPanel line = new JPanel(new BorderLayout());
		line.setOpaque(false);
		line.add(Ui.label(gap.getSkill().getName(), Theme.small(), gap.isMet() ? Theme.TEXT_MUTED : Theme.TEXT), BorderLayout.WEST);
		line.add(Ui.label(gap.getCurrent() + " / " + gap.getTarget(), Theme.small(), gap.isMet() ? Theme.GREEN : Theme.GOLD),
			BorderLayout.EAST);
		right.add(line, BorderLayout.NORTH);
		ProgressBar bar = new ProgressBar(4);
		bar.setProgress(gap.fraction(), gap.isMet(), false);
		right.add(bar, BorderLayout.CENTER);
		row.add(right, BorderLayout.CENTER);
		if (!gap.isMet())
		{
			row.setToolTipText(com.codex.navigator.core.Planner.formatXp(gap.xpToGo()) + " xp to go");
		}
		return row;
	}

	private static JPanel spacer(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new java.awt.Dimension(1, height));
		spacer.setMaximumSize(new java.awt.Dimension(1, height));
		spacer.setAlignmentX(JPanel.LEFT_ALIGNMENT);
		return spacer;
	}
}

package com.codex.navigator.ui;

import com.codex.navigator.core.Step;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A drawn status mark: a sealed check, a half moon, a lit ring, a lock or a question. */
public class Glyph extends JComponent
{
	private final int size;
	private Step.Status status;

	public Glyph(Step.Status status, int size)
	{
		this.status = status;
		this.size = size;
		Dimension d = new Dimension(size, size);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
	}

	public void setStatus(Step.Status status)
	{
		this.status = status;
		repaint();
	}

	public static Color color(Step.Status status)
	{
		switch (status)
		{
			case DONE:
				return Theme.GREEN;
			case IN_PROGRESS:
				return Theme.GOLD_BRIGHT;
			case READY:
				return Theme.TEAL;
			case BLOCKED:
				return Theme.BLOCKED;
			default:
				return Theme.TEXT_FAINT;
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		float s = size - 2;
		float o = 1;
		Color c = color(status);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		Ellipse2D circle = new Ellipse2D.Float(o, o, s, s);
		switch (status)
		{
			case DONE:
			{
				g.setColor(Theme.alpha(c, 60));
				g.fill(circle);
				g.setColor(c);
				g.draw(circle);
				Path2D check = new Path2D.Float();
				check.moveTo(o + s * 0.28, o + s * 0.52);
				check.lineTo(o + s * 0.44, o + s * 0.68);
				check.lineTo(o + s * 0.74, o + s * 0.34);
				g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
				g.draw(check);
				break;
			}
			case IN_PROGRESS:
			{
				g.setColor(Theme.alpha(c, 40));
				g.fill(circle);
				g.setColor(c);
				g.fill(new Arc2D.Float(o, o, s, s, 90, 180, Arc2D.PIE));
				g.draw(circle);
				break;
			}
			case READY:
			{
				g.setColor(Theme.alpha(c, 50));
				g.fill(new Ellipse2D.Float(o - 0.5f, o - 0.5f, s + 1, s + 1));
				g.setColor(c);
				g.draw(circle);
				float dot = s * 0.36f;
				g.fill(new Ellipse2D.Float(o + (s - dot) / 2, o + (s - dot) / 2, dot, dot));
				break;
			}
			case BLOCKED:
			{
				g.setColor(Theme.alpha(c, 170));
				g.draw(circle);
				float bw = s * 0.42f;
				float bh = s * 0.30f;
				float bx = o + (s - bw) / 2;
				float by = o + s * 0.46f;
				g.fill(new RoundRectangle2D.Float(bx, by, bw, bh, 2, 2));
				g.draw(new Arc2D.Float(bx + bw * 0.18f, by - bh * 0.85f, bw * 0.64f, bh * 1.5f, 0, 180, Arc2D.OPEN));
				break;
			}
			default:
			{
				g.setColor(c);
				g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1, new float[]{2f, 2f}, 0));
				g.draw(circle);
				g.setFont(Theme.small());
				String q = "?";
				int w = g.getFontMetrics().stringWidth(q);
				g.drawString(q, Math.round(o + (s - w) / 2f), Math.round(o + s / 2f + 4));
			}
		}
		g.dispose();
	}
}

package com.codex.navigator.ui;

import com.codex.navigator.core.Plan;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** A pinned goal: ring, title and the next step, in a large or compact size. */
final class GoalCard
{
	private GoalCard()
	{
	}

	static Card build(Navigation nav, Plan plan, boolean focus, boolean showActions)
	{
		Card card = new Card(new BorderLayout(0, 8));
		card.setBorder(new EmptyBorder(10, 10, 10, 10));
		card.highlighted(focus);
		card.accent(plan.isComplete() ? Theme.GREEN : Theme.progressColor(plan.getProgress()));

		JPanel top = new JPanel(new BorderLayout(10, 0));
		top.setOpaque(false);
		ProgressRing ring = new ProgressRing(focus ? 50 : 40, focus ? 5f : 4f);
		ring.setProgress(plan.getProgress(), plan.isComplete(), false);
		JPanel ringHolder = new JPanel(new BorderLayout());
		ringHolder.setOpaque(false);
		ringHolder.add(ring, BorderLayout.NORTH);
		top.add(ringHolder, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		if (focus)
		{
			text.add(Ui.label("FOCUS", Theme.small(), Theme.GOLD));
		}
		text.add(Ui.wrapped(plan.getTitle(), Theme.title(), Theme.GOLD_BRIGHT, focus ? 124 : 136));
		String sub = plan.getSubtitle();
		if (plan.getQuestsTotal() > 1)
		{
			sub += "  ·  " + plan.getQuestsDone() + "/" + plan.getQuestsTotal() + " quests";
		}
		text.add(Ui.wrapped(sub, Theme.small(), Theme.TEXT_MUTED, focus ? 124 : 136));
		top.add(text, BorderLayout.CENTER);
		card.add(top, BorderLayout.NORTH);

		if (focus || !plan.isComplete())
		{
			card.add(new NextStepBox(plan.getNext(), 150), BorderLayout.CENTER);
		}

		if (showActions)
		{
			JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
			actions.setOpaque(false);
			if (!focus)
			{
				actions.add(new CodexButton("Focus", false, () -> nav.goals().makeFocus(plan.getGoal())));
			}
			actions.add(new CodexButton("Unpin", false, () -> nav.goals().toggle(plan.getGoal())));
			card.add(actions, BorderLayout.SOUTH);
		}
		card.onClick(() -> nav.open(plan.getGoal()));
		return card;
	}

	static JLabel hint(String text)
	{
		return Ui.wrapped(text, Theme.small(), Theme.TEXT_FAINT, 190);
	}
}

package com.codex.navigator.ui;

import com.codex.navigator.core.Goal;
import com.codex.navigator.core.Plan;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.util.List;
import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Every pinned goal, focus first. */
final class GoalsView
{
	private GoalsView()
	{
	}

	static StackPanel build(Navigation nav)
	{
		StackPanel stack = new StackPanel(6, 8);
		List<Goal> goals = nav.goals().goals();
		if (goals.isEmpty())
		{
			Card card = new Card(new BorderLayout(0, 8));
			card.setBorder(new EmptyBorder(12, 10, 12, 10));
			JPanel text = new JPanel();
			text.setOpaque(false);
			text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
			text.add(Ui.label("NO GOALS PINNED", Theme.small(), Theme.GOLD));
			text.add(Ui.wrapped("Open anything in the Atlas and press Pin goal. The first goal you pin becomes your focus.",
				Theme.body(), Theme.TEXT, 168));
			card.add(text, BorderLayout.CENTER);
			JPanel actions = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			actions.setOpaque(false);
			actions.add(new CodexButton("Browse the Atlas", true, () -> nav.showTab(2)));
			card.add(actions, BorderLayout.SOUTH);
			stack.add(card);
			return stack;
		}

		stack.add(new SectionHeader("Pinned", String.valueOf(goals.size())));
		boolean first = true;
		for (Goal goal : goals)
		{
			Plan plan = nav.planner().plan(goal, nav.account());
			stack.add(GoalCard.build(nav, plan, first, true));
			first = false;
		}
		stack.add(GoalCard.hint("Your focus also shows in game. Turn the overlay off in the plugin settings."));
		return stack;
	}
}

package com.codex.navigator.ui;

import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** Draws the Codex compass rose used for the sidebar button. */
public final class Icons
{
	private Icons()
	{
	}

	public static BufferedImage compass(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		float c = size / 2f;
		float r = size / 2f - 1;
		g.setStroke(new BasicStroke(Math.max(1f, size / 14f)));
		g.setColor(Theme.GOLD_DIM);
		g.draw(new Ellipse2D.Float(c - r, c - r, r * 2, r * 2));

		// Four long points in gold, the north one lit teal.
		float l = r * 0.92f;
		float w = r * 0.26f;
		Path2D north = diamondPoint(c, c, 0, -l, w);
		Path2D south = diamondPoint(c, c, 0, l, w);
		Path2D east = diamondPoint(c, c, l, 0, w);
		Path2D west = diamondPoint(c, c, -l, 0, w);
		g.setColor(Theme.GOLD);
		g.fill(south);
		g.fill(east);
		g.fill(west);
		g.setColor(Theme.TEAL);
		g.fill(north);
		g.setColor(Theme.GOLD_BRIGHT);
		float dot = Math.max(2f, size / 8f);
		g.fill(new Ellipse2D.Float(c - dot / 2, c - dot / 2, dot, dot));
		g.dispose();
		return image;
	}

	private static Path2D diamondPoint(float cx, float cy, float dx, float dy, float width)
	{
		float len = (float) Math.hypot(dx, dy);
		float nx = -dy / len * width;
		float ny = dx / len * width;
		Path2D p = new Path2D.Float();
		p.moveTo(cx + dx, cy + dy);
		p.lineTo(cx + nx, cy + ny);
		p.lineTo(cx, cy);
		p.lineTo(cx - nx, cy - ny);
		p.closePath();
		return p;
	}
}

