package com.codex.navigator.ui;

import com.codex.navigator.core.AccountSnapshot;
import com.codex.navigator.core.Goal;
import com.codex.navigator.core.GoalStore;
import com.codex.navigator.core.Planner;
import com.codex.navigator.core.Recommender;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Graphics;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.BooleanSupplier;
import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Skill;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The Codex side panel: the account crest, three tabs (Compass, Goals, Atlas)
 * and a detail page that opens over them for any goal.
 */
public class NavigatorPanel extends PluginPanel implements Navigation
{
	private static final String[] TABS = {"compass", "goals", "atlas"};
	private static final String DETAIL = "detail";

	private final Planner planner;
	private final Recommender recommender;
	private final GoalStore goals;
	private final SkillIconManager skillIcons;
	private final BooleanSupplier includeMiniquests;
	private final Map<Skill, BufferedImage> iconCache = new EnumMap<>(Skill.class);

	private final CrestHeader crest = new CrestHeader();
	private final Segmented tabs = new Segmented(true, "Compass", "Goals", "Atlas");
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane compass = scroller(new StackPanel(6, 8));
	private final JScrollPane goalsView = scroller(new StackPanel(6, 8));
	private final AtlasView atlas;
	private final JScrollPane detail = scroller(new StackPanel(6, 8));

	private final Deque<Goal> history = new ArrayDeque<>();
	private AccountSnapshot account = AccountSnapshot.empty();
	private Goal detailGoal;
	private boolean showCompleted;

	public NavigatorPanel(Planner planner, Recommender recommender, GoalStore goals, SkillIconManager skillIcons,
		BooleanSupplier includeMiniquests)
	{
		super(false);
		this.planner = planner;
		this.recommender = recommender;
		this.goals = goals;
		this.skillIcons = skillIcons;
		this.includeMiniquests = includeMiniquests;
		this.atlas = new AtlasView(this);

		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(compass, TABS[0]);
		content.add(goalsView, TABS[1]);
		content.add(atlas, TABS[2]);
		content.add(detail, DETAIL);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		goals.addListener(() -> SwingUtilities.invokeLater(this::rebuildAll));
		rebuildAll();
	}

	static JScrollPane scroller(JComponent view)
	{
		JScrollPane scroll = new JScrollPane(view);
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new java.awt.Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread whenever the account changes. */
	public void update(AccountSnapshot snapshot)
	{
		account = snapshot;
		crest.update(snapshot, planner.getData());
		rebuildAll();
	}

	private void rebuildAll()
	{
		replace(compass, CompassView.build(this));
		replace(goalsView, GoalsView.build(this));
		atlas.rebuild();
		if (detailGoal != null)
		{
			replace(detail, DetailView.build(this, detailGoal, showCompleted, this::back, this::toggleCompleted));
		}
		revalidate();
		repaint();
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	public void showTab(int tab)
	{
		detailGoal = null;
		history.clear();
		tabs.setSelected(tab, false);
		cards.show(content, TABS[tab]);
	}

	@Override
	public void open(Goal goal)
	{
		if (detailGoal != null)
		{
			history.push(detailGoal);
		}
		detailGoal = goal;
		showCompleted = false;
		detail.setViewportView(DetailView.build(this, goal, false, this::back, this::toggleCompleted));
		detail.getVerticalScrollBar().setValue(0);
		cards.show(content, DETAIL);
	}

	private void back()
	{
		if (history.isEmpty())
		{
			showTab(tabs.getSelected());
			return;
		}
		detailGoal = history.pop();
		showCompleted = false;
		detail.setViewportView(DetailView.build(this, detailGoal, false, this::back, this::toggleCompleted));
		detail.getVerticalScrollBar().setValue(0);
	}

	private void toggleCompleted()
	{
		showCompleted = !showCompleted;
		replace(detail, DetailView.build(this, detailGoal, showCompleted, this::back, this::toggleCompleted));
	}

	@Override
	public AccountSnapshot account()
	{
		return account;
	}

	@Override
	public Planner planner()
	{
		return planner;
	}

	@Override
	public Recommender recommender()
	{
		return recommender;
	}

	@Override
	public GoalStore goals()
	{
		return goals;
	}

	@Override
	public boolean includeMiniquests()
	{
		return includeMiniquests.getAsBoolean();
	}

	@Override
	public BufferedImage skillIcon(Skill skill)
	{
		return iconCache.computeIfAbsent(skill, s -> skillIcons.getSkillImage(s, true));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.navigator.ui;

import com.codex.navigator.core.Step;
import java.awt.BorderLayout;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** The single most important line in the plugin: what to do next, set into a dark inlay. */
public class NextStepBox extends JPanel
{
	public NextStepBox(Step step, int textWidth)
	{
		super(new BorderLayout(8, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(7, 8, 7, 8));

		JPanel glyph = new JPanel(new BorderLayout());
		glyph.setOpaque(false);
		glyph.setBorder(new EmptyBorder(2, 0, 0, 0));
		glyph.add(new Glyph(step == null ? Step.Status.DONE : step.getStatus(), 14), BorderLayout.NORTH);
		add(glyph, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setOpaque(false);
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(Ui.label(step == null ? "COMPLETE" : "NEXT STEP", Theme.small(), Theme.GOLD));
		String title = step == null ? "Nothing left to do here" : verb(step) + step.getTitle();
		JLabel titleLabel = Ui.wrapped(title, Theme.body(), Theme.TEXT, textWidth);
		text.add(titleLabel);
		if (step != null && step.getDetail() != null && !step.getDetail().isEmpty())
		{
			text.add(Ui.wrapped(step.getDetail(), Theme.small(), Theme.TEXT_MUTED, textWidth));
		}
		add(text, BorderLayout.CENTER);
	}

	private static String verb(Step step)
	{
		if (step.getKind() != Step.Kind.QUEST)
		{
			return "";
		}
		return step.getStatus() == Step.Status.IN_PROGRESS ? "Continue " : "Start ";
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setPaint(new GradientPaint(0, 0, Theme.INK_DEEP, 0, h, Theme.mix(Theme.INK_DEEP, Theme.TEAL, 0.06)));
		g.fill(shape);
		g.setColor(Theme.alpha(Theme.TEAL, 70));
		g.draw(shape);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.navigator.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tag, such as "Opens 12 more" or "Master". */
public class Pill extends JComponent
{
	private final String text;
	private final Color color;

	public Pill(String text, Color color)
	{
		this.text = text;
		this.color = color;
		setFont(Theme.small());
		setOpaque(false);
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 12, fm.getHeight() + 3);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, h, h);
		g.setColor(Theme.alpha(color, 34));
		g.fill(shape);
		g.setColor(Theme.alpha(color, 120));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(color);
		g.drawString(text, (w - fm.stringWidth(text)) / 2, (h + fm.getAscent()) / 2 - 1);
		g.dispose();
	}
}

package com.codex.navigator.ui;

import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A slim rounded bar that fills with the same ember-to-teal ramp as the rings. */
public class ProgressBar extends JComponent
{
	private final Animator animator = new Animator(this);
	private boolean complete;

	public ProgressBar(int height)
	{
		setPreferredSize(new Dimension(10, height));
		setMinimumSize(new Dimension(10, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		setOpaque(false);
	}

	public void setProgress(double progress, boolean complete, boolean animate)
	{
		this.complete = complete;
		animator.set(Math.max(0, Math.min(1, progress)), animate);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float arc = h;
		g.setColor(Theme.INK_DEEP);
		g.fill(new RoundRectangle2D.Float(0, 0, w, h, arc, arc));
		double value = animator.get();
		if (value > 0)
		{
			float fill = (float) Math.max(h, w * value);
			if (complete)
			{
				g.setColor(Theme.GREEN);
			}
			else
			{
				g.setPaint(new GradientPaint(0, 0, Theme.progressColor(0), w, 0, Theme.progressColor(1)));
			}
			g.fill(new RoundRectangle2D.Float(0, 0, fill, h, arc, arc));
			g.setColor(Theme.alpha(java.awt.Color.WHITE, 40));
			g.drawLine(Math.round(arc / 2), 0, Math.round(fill - arc / 2), 0);
		}
		g.setColor(Theme.alpha(Theme.STROKE, 160));
		g.draw(new RoundRectangle2D.Float(0, 0, w - 1, h - 1, arc, arc));
		g.dispose();
	}
}

